// Atomic read from specific offset
ssize_t pread(int fd, void *buf, size_t count, off_t offset);

int file_fd;
char buffer[256];
size_t length = 128;
off_t start = 4096; // Read starts here

// Read length bytes into buffer from file offset start
ssize_t bytes_transferred = pread(
    file_fd,
    buffer,
    length,
    start
);

// If bytes_transferred == -1, error occurred.

// Guarantee:
// The file descriptor's internal position is NOT modified.
// Useful for multi-threaded file access (atomic operation).
